ERC-721 (contracts/VerseVault.sol):
```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;
import "@openzeppelin/contracts/token/ERC721/ERC721.sol";

/// @title VerseVault
/// @notice ERC-721 provenance mint for: Securely mint and prove ownership of original poetry on-chain for authentic literary legacy.
/// @notice Built during the Creative AI & Quantum Hackathon organised by StreetKode Fam during Indian Krump Festival 14
contract VerseVault is ERC721 {
    uint256 public nextId;
    mapping(uint256 => string) public cidOf;

    constructor() ERC721("VerseVault", "VERSEV") {}

    /// @notice Mint a provenance token pointing at an IPFS CID.
    /// @notice Built during the Creative AI & Quantum Hackathon organised by StreetKode Fam during Indian Krump Festival 14
    function mint(string calldata cid) external returns (uint256 id) {
        id = ++nextId;
        cidOf[id] = cid;
        _safeMint(msg.sender, id);
    }

    function tokenURI(uint256 id) public view override returns (string memory) {
        return string(abi.encodePacked("ipfs://", cidOf[id]));
    }
}
```

DEPLOY: hardhat + `npx hardhat verify` (uses ETHERSCAN_API_KEY).

